import { ParticleCanvas } from 'wgpu-kit/react';
export function Simulation({ seed }: { seed: string }) {
  return (
    <div style={{ height: 400 }}>
      <ParticleCanvas
        key={seed}
        seed={seed}
        count={4096}
        mode="grid"
        style={{ background: '#000' }}
        onReady={sim => sim.setParams({ forceFactor: 8 })}
      />
    </div>
  );
}
